// Function to set up cascading dropdowns for a specific player
function setupPlayerDropdowns(playerIndex) {
    const uniSelect = document.getElementById(`universitySelect${playerIndex}`);
    const facSelect = document.getElementById(`facultySelect${playerIndex}`);
    const degSelect = document.getElementById(`degreeSelect${playerIndex}`);

    // Update faculties when university changes
    uniSelect.addEventListener('change', () => {
        const uni = uniSelect.value;
        
        // Reset lower-level dropdowns
