      }
  });

  // Envío del Formulario
  form.addEventListener('submit', function(e) {
      e.preventDefault(); 
      let allValid = true;
      const inputs = form.querySelectorAll('input[type="number"]');

      inputs.forEach(input => {
          const value = Number(input.value);
          if (input.value.trim() === '' || !Number.isInteger(value) || value < 0 || value > 10) {
              allValid = false;
              input.style.border = '2px solid #dc3545'; 
          } else {
              input.style.border = '1px solid #ccc';
              const stockLevel = input.getAttribute('data-stock');
              
              // GUARDAMOS LAS DECISIONES CON EL IDENTIFICADOR _noinfo_game1
              ds.set(`strategy_time_noinfo_stock_${stockLevel}_game1`, value);
          }
      });

      if (allValid) {
          errorMsg.style.display = 'none';
          if(typeof this.end === 'function') {
              this.end();
          }
      } else {
          errorMsg.style.display = 'block';
      }
  }.bind(this));
